BEGIN;
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT public.save_server_community(community_test.id('a'),community_test.payload('a'),0);
SELECT public.set_community_role_permission(community_test.id('a'),community_test.id('delegate-role'),true);
INSERT INTO public.channels(id,server_id,name,type) VALUES('ca000000-0000-0000-0000-000000000001',community_test.id('a'),'encontros','voice');
CREATE TEMP TABLE event_fixture AS SELECT jsonb_build_object('title','Encontro técnico','description','Evento sintético, não publicar.',
 'cover_url',NULL,'channel_id','ca000000-0000-0000-0000-000000000001','starts_at',clock_timestamp()+interval '1 day','ends_at',NULL,'timezone','America/Sao_Paulo') AS payload;
CREATE TEMP TABLE original_event_base AS SELECT community_test.snapshot() AS value;
SELECT public.save_community_event(community_test.id('a'),'ce000000-0000-0000-0000-000000000001',(SELECT payload FROM event_fixture),0);
SELECT community_test.assert((public.save_community_event(community_test.id('a'),'ce000000-0000-0000-0000-000000000001',(SELECT payload FROM event_fixture),0)->>'revision')::integer=1,'create retry is idempotent');
SELECT community_test.assert(jsonb_array_length(public.list_community_events(community_test.id('a'))->'items')=1,'actual upcoming list');
SELECT community_test.assert(NOT (public.list_community_events(community_test.id('a'))->'items'->0 ? 'created_by'),'projection strips actors');
SAVEPOINT event_audit_failure;
RESET ROLE;
CREATE FUNCTION community_test.reject_event_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.action='community_event_created' THEN RAISE EXCEPTION 'synthetic_event_audit_failure'; END IF; RETURN NEW; END $$;
CREATE TRIGGER synthetic_event_audit_failure BEFORE INSERT ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION community_test.reject_event_audit();
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT community_test.denied($sql$SELECT public.save_community_event(community_test.id('a'),'ce000000-0000-0000-0000-000000000002',(SELECT payload FROM event_fixture),0)$sql$,'P0001','synthetic_event_audit_failure');
SELECT community_test.assert(NOT EXISTS(SELECT id FROM public.community_events WHERE id='ce000000-0000-0000-0000-000000000002'),'failed audit rolls back event creation');
ROLLBACK TO SAVEPOINT event_audit_failure;

SELECT community_test.denied('SELECT * FROM public.community_events','42501');
SELECT community_test.denied($sql$INSERT INTO public.community_events(id,server_id,channel_id,title,starts_at,timezone) VALUES(gen_random_uuid(),community_test.id('a'),community_test.id('a-welcome'),'bad',now(),'UTC')$sql$,'42501');
SELECT community_test.denied($sql$SELECT public.save_community_event(community_test.id('a'),gen_random_uuid(),jsonb_set((SELECT payload FROM event_fixture),'{channel_id}',to_jsonb(community_test.id('b-welcome'))),0)$sql$,'22023');
SELECT community_test.denied($sql$SELECT public.save_community_event(community_test.id('a'),gen_random_uuid(),jsonb_set((SELECT payload FROM event_fixture),'{cover_url}','"https://user:secret@example.test/x"'),0)$sql$,'22023');
SELECT community_test.denied($sql$SELECT public.save_community_event(community_test.id('a'),gen_random_uuid(),jsonb_set((SELECT payload FROM event_fixture),'{timezone}','"Unknown/Zone"'),0)$sql$,'22023');
SELECT community_test.denied($sql$SELECT public.save_community_event(community_test.id('a'),gen_random_uuid(),jsonb_set((SELECT payload FROM event_fixture),'{starts_at}','"2026-01-01T00:00:00"'),0)$sql$,'22023');
SELECT community_test.denied($sql$SELECT public.save_community_event(community_test.id('a'),gen_random_uuid(),jsonb_set((SELECT payload FROM event_fixture),'{ends_at}',to_jsonb(now())),0)$sql$,'22023');
SELECT community_test.denied($sql$SELECT public.save_community_event(community_test.id('a'),gen_random_uuid(),jsonb_set((SELECT payload FROM event_fixture),'{starts_at}',to_jsonb(now()-interval '1 day')),0)$sql$,'22023');
SELECT community_test.actor(2);
SELECT public.save_community_event(community_test.id('a'),'ce000000-0000-0000-0000-000000000001',(SELECT payload FROM event_fixture),1);
SELECT community_test.actor(3);
SELECT community_test.denied($sql$SELECT public.save_community_event(community_test.id('a'),gen_random_uuid(),(SELECT payload FROM event_fixture),0)$sql$,'42501');
SELECT community_test.actor(5);
SELECT community_test.denied($sql$SELECT public.cancel_community_event('ce000000-0000-0000-0000-000000000001',1)$sql$,'42501');
SELECT public.respond_community_event('ce000000-0000-0000-0000-000000000001',1,'interested',true);
SELECT public.respond_community_event('ce000000-0000-0000-0000-000000000001',1,'going',true);
SELECT community_test.assert((public.list_community_events(community_test.id('a'))->'items'->0->>'going_count')::integer=1,'RSVP updated without double counting');
SELECT community_test.denied($sql$INSERT INTO public.community_event_rsvps(event_id,member_id,response) SELECT 'ce000000-0000-0000-0000-000000000001',id,'going' FROM public.server_members WHERE user_id=auth.uid()$sql$,'42501');
SELECT community_test.denied('SELECT public.dispatch_community_event_notifications(100)','42501');
SELECT community_test.actor(6);
SELECT community_test.assert((SELECT count(*)=0 FROM public.community_event_rsvps),'other member cannot see RSVP identities');
SELECT public.respond_community_event('ce000000-0000-0000-0000-000000000001',1,'interested',false);
SELECT community_test.actor(8);
SELECT community_test.denied($sql$SELECT public.list_community_events(community_test.id('a'))$sql$,'42501');
SELECT community_test.assert(jsonb_array_length(public.list_community_events(community_test.id('b'))->'items')=0,'common server has no events');
SELECT community_test.assert(NOT (public.list_community_events(community_test.id('b'))->>'can_manage')::boolean,'common server cannot manage events');
SELECT community_test.actor(1);
UPDATE event_fixture SET payload=jsonb_set(payload,'{description}','"Primeira alteração"');
SELECT public.save_community_event(community_test.id('a'),'ce000000-0000-0000-0000-000000000001',(SELECT payload FROM event_fixture),1);
SELECT community_test.denied($sql$SELECT public.save_community_event(community_test.id('a'),'ce000000-0000-0000-0000-000000000001',(SELECT payload FROM event_fixture),1)$sql$,'40001');
SELECT community_test.actor(5);
SELECT community_test.denied($sql$SELECT public.respond_community_event('ce000000-0000-0000-0000-000000000001',1,'going',true)$sql$,'40001');
RESET ROLE;
SELECT community_test.assert(public.dispatch_community_event_notifications(100)=1,'worker queues update only for opted-in member');
SELECT community_test.assert(public.dispatch_community_event_notifications(100)=0,'worker replay is idempotent');
SET LOCAL ROLE authenticated;
SELECT community_test.actor(6);
SELECT community_test.assert(jsonb_array_length(public.list_my_community_event_notifications())=0,'opt-out receives no update');
SELECT community_test.actor(5);
SELECT community_test.assert(jsonb_array_length(public.list_my_community_event_notifications())=1,'opt-in update delivered persistently');
SELECT public.read_community_event_notifications(ARRAY(SELECT id FROM public.community_event_notifications));
SELECT community_test.assert(jsonb_array_length(public.list_my_community_event_notifications())=0,'read own inbox');
SELECT community_test.actor(1);
UPDATE event_fixture SET payload=jsonb_set(payload,'{starts_at}',to_jsonb(clock_timestamp()+interval '5 minutes'));
SELECT public.save_community_event(community_test.id('a'),'ce000000-0000-0000-0000-000000000001',(SELECT payload FROM event_fixture),2);
RESET ROLE;
SELECT community_test.assert(public.dispatch_community_event_notifications(100)=1,'due reminder and update batched once');
SELECT community_test.assert(public.dispatch_community_event_notifications(100)=0,'reminder does not repeat');
SET LOCAL ROLE authenticated;
SELECT community_test.actor(5);
SELECT community_test.assert(jsonb_array_length(public.list_my_community_event_notifications())=2,'update and due reminder exist');
SELECT community_test.actor(1);
SELECT public.cancel_community_event('ce000000-0000-0000-0000-000000000001',3);
SELECT public.cancel_community_event('ce000000-0000-0000-0000-000000000001',4);
SELECT community_test.denied($sql$SELECT public.save_community_event(community_test.id('a'),'ce000000-0000-0000-0000-000000000001',(SELECT payload FROM event_fixture),4)$sql$,'22023');
SELECT community_test.assert(jsonb_array_length(public.list_community_events(community_test.id('a'),'cancelled')->'items')=1,'cancelled history retained');
SELECT community_test.assert((SELECT value FROM original_event_base)=community_test.snapshot(),'events do not change IDs, messages, members, roles, channels, invites or XP');
RESET ROLE;
SELECT community_test.assert(public.dispatch_community_event_notifications(100)=1,'cancel notification queued');
SELECT community_test.assert((SELECT count(*)=2 FROM public.community_event_rsvps WHERE event_id='ce000000-0000-0000-0000-000000000001'),'cancellation preserves RSVP history');
SELECT community_test.denied('SELECT public.dispatch_community_event_notifications(501)','22023');
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
INSERT INTO public.roles(id,server_id,name,permissions) VALUES('cb000000-0000-0000-0000-000000000001',community_test.id('a'),'Sem acesso','{"view_channel":false}');
INSERT INTO public.member_roles(member_id,role_id) SELECT id,'cb000000-0000-0000-0000-000000000001' FROM public.server_members WHERE server_id=community_test.id('a') AND user_id=community_test.user_id(5);
SELECT community_test.actor(5);
SELECT community_test.assert(NOT public.can_view_community_event('ce000000-0000-0000-0000-000000000001') AND jsonb_array_length(public.list_my_community_event_notifications())=0,'revoked channel access hides event and inbox');
SELECT community_test.actor(1);
SELECT public.set_community_role_permission(community_test.id('a'),community_test.id('delegate-role'),false);
SELECT community_test.actor(2);
SELECT community_test.denied($sql$SELECT public.save_community_event(community_test.id('a'),gen_random_uuid(),(SELECT payload FROM event_fixture),0)$sql$,'42501');
SELECT community_test.actor(1);
INSERT INTO public.server_bans(server_id,user_id,banned_by) VALUES(community_test.id('a'),community_test.user_id(6),auth.uid());
SELECT community_test.actor(6);
SELECT community_test.denied($sql$SELECT public.list_community_events(community_test.id('a'))$sql$,'42501');
SELECT community_test.actor(1);
DELETE FROM public.channels WHERE id='ca000000-0000-0000-0000-000000000001';
SELECT community_test.actor(2);
SELECT community_test.assert(NOT public.can_view_community_event('ce000000-0000-0000-0000-000000000001'),'removed channel never makes event public');
SET LOCAL ROLE anon;
SELECT community_test.denied($sql$SELECT public.list_community_events(community_test.id('a'))$sql$,'42501');
RESET ROLE;
-- Synthetic paging fixture, no real user records and no bypass in production code.
INSERT INTO public.community_events(id,server_id,channel_id,title,starts_at,timezone)
 SELECT gen_random_uuid(),community_test.id('a'),community_test.id('a-welcome'),'Page '||n,now()+interval '2 days','UTC' FROM generate_series(1,25) n;
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
CREATE TEMP TABLE page_one AS SELECT public.list_community_events(community_test.id('a'),'upcoming',NULL,NULL,12) AS v;
SELECT community_test.assert((SELECT (v->>'has_more')::boolean AND jsonb_array_length(v->'items')=12 FROM page_one),'bounded first page');
CREATE TEMP TABLE page_two AS SELECT public.list_community_events(community_test.id('a'),'upcoming',(v->'items'->11->>'starts_at')::timestamptz,(v->'items'->11->>'id')::uuid,12) AS v FROM page_one;
SELECT community_test.assert(NOT EXISTS(SELECT FROM page_one a,page_two b,jsonb_array_elements(a.v->'items') x,jsonb_array_elements(b.v->'items') y WHERE x->>'id'=y->>'id'),'cursor tie-break avoids duplicate rows');
SELECT public.disable_server_community(community_test.id('a'),1);
SELECT community_test.assert(jsonb_array_length(public.list_community_events(community_test.id('a'))->'items')=0,'deactivation hides event content');
ROLLBACK;
SELECT 'PASS: events, RSVP, permissions, revision conflicts, privacy, bounded reminders, cancellation and pagination';
